source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    lines = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != background:
            lines.append(("row", r, row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != background:
            lines.append(("col", c, vals[0]))
    for kind, i, _ in lines:
        if kind == "row":
            out[i] = [2] * w
        else:
            for r in range(h):
                out[r][i] = 2
    return out
'''
